  margin-top: 0.5rem;
  padding-left: calc(1.125rem + 0.625rem); /* indent to align with label */
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  line-height: 1.5;
}

.field-error {
  margin-top: 0.5rem;
  padding-left: calc(1.125rem + 0.625rem);
  font-size: 0.8125rem;
  color: var(--color-error);
  line-height: 1.5;
  font-weight: 500;
