  border: 1px solid #bbf7d0;
  border-radius: var(--radius-field);
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-success);
}
.success-message[hidden] { display: none; }

/* ── Forced colors (Windows High Contrast) ───────────────── */
